function validate([s]) {
  if (s.length < 1 || s.length > 100000) return 's needs 1 to 10^5 characters.';
  if (s.some(ch => !/^[A-Za-z0-9 ]$/.test(ch))) return 'Each character is a letter, a digit or a space.';
  if (s[0] === ' ' || s[s.length - 1] === ' ') return 's has no space at the start or the end.';
  if (s.some((ch, i) => ch === ' ' && s[i + 1] === ' ')) return 'Words are separated by exactly one space.';
  return null;
}

