function reverseWords(s) {
  function reverse(left, right) {
    while (left < right) {
      const temp = s[left];
      s[left] = s[right];
      s[right] = temp;
      left++;
      right--;
    }
  }

  reverse(0, s.length - 1);
  let start = 0;
  for (let end = 0; end <= s.length; end++) {
    if (end === s.length || s[end] === ' ') {
      reverse(start, end - 1);
      start = end + 1;
    }
  }
}

