function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const alphabet = rand() < 0.5 ? 'ab' : 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  const limit = size === 'large' ? 2000 : 12;
  const longest = size === 'large' ? 1 + pick(20) : 1 + pick(4);
  const words = [];
  let length = -1;
  for (;;) {
    const word = Array.from({ length: 1 + pick(longest) }, () => alphabet[pick(alphabet.length)]).join('');
    if (length + 1 + word.length > limit || (size === 'small' && words.length && rand() < 0.25)) break;
    words.push(word);
    length += 1 + word.length;
  }
  return [words.join(' ').split('')];
}
